// @ts-nocheck
"use client";

import React, { useState } from "react";
import Link from "next/link";
import dynamic from "next/dynamic";
import { motion } from "framer-motion";
import { Fraunces, Inter, IBM_Plex_Mono } from "next/font/google";
import { Eye, EyeOff, ArrowRight } from "lucide-react";

const fraunces = Fraunces({ subsets: ["latin"], weight: ["400", "500", "600"], variable: "--font-display" });
const inter = Inter({ subsets: ["latin"], weight: ["400", "500", "600"], variable: "--font-body" });
const plexMono = IBM_Plex_Mono({ subsets: ["latin"], weight: ["400", "500"], variable: "--font-mono" });

// Reusing your existing Network3D component — adjust this path to match
// your project structure (see note below the code).
const Network3D = dynamic(() => import("@/components/Network3D"), {
  ssr: false,
  loading: () => <div className="w-full h-full" />,
});

const MANIFEST: { code: string; route: string; status: "active" | "blocked" | "pending"; eta: string }[] = [
  { code: "MRD-3391", route: "SHA → SIN", status: "active", eta: "14:02Z" },
  { code: "MRD-3388", route: "SIN → SUEZ", status: "blocked", eta: "—" },
  { code: "MRD-3402", route: "RTM → FRA", status: "active", eta: "11:47Z" },
  { code: "MRD-3390", route: "DXB → FRA", status: "pending", eta: "22:15Z" },
];

const fade = {
  hidden: { opacity: 0, y: 14 },
  show: (i = 0) => ({
    opacity: 1,
    y: 0,
    transition: { delay: 0.15 + i * 0.07, duration: 0.55, ease: [0.22, 1, 0.36, 1] },
  }),
};

// Matched to Network3D's own status palette (emerald / amber / rose)
function StatusDot({ status }: { status: "active" | "blocked" | "pending" }) {
  const color =
    status === "active" ? "bg-emerald-500" : status === "blocked" ? "bg-rose-500" : "bg-amber-500";
  return <span className={`inline-block w-1.5 h-1.5 rounded-full ${color}`} />;
}

export default function SignInPage() {
  const [showPassword, setShowPassword] = useState(false);

  return (
    <div
      className={`${fraunces.variable} ${inter.variable} ${plexMono.variable} min-h-screen bg-[#0B0D12] text-[#F2F3F5]`}
      style={{ fontFamily: "var(--font-body)" }}
    >
      <style jsx global>{`
        @media (prefers-reduced-motion: reduce) {
          * { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
        }
        input:-webkit-autofill {
          -webkit-box-shadow: 0 0 0 1000px #13161d inset !important;
          -webkit-text-fill-color: #f2f3f5 !important;
        }
      `}</style>

      <div className="min-h-screen grid grid-cols-1 lg:grid-cols-[minmax(0,480px)_1fr]">
        {/* ---------------- Left: Sign-in ---------------- */}
        <div className="flex flex-col justify-between px-8 sm:px-14 py-10 border-r border-[#262B36]">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5 }}
            className="flex items-center gap-3"
          >
            <svg width="30" height="30" viewBox="0 0 30 30" fill="none">
              <circle cx="15" cy="15" r="13.5" stroke="#C79A4B" strokeWidth="1" />
              <circle cx="15" cy="15" r="9.5" stroke="#C79A4B" strokeWidth="1" opacity="0.5" />
              <text x="15" y="19.5" textAnchor="middle" fontFamily="var(--font-display)" fontSize="12" fill="#C79A4B">
                M
              </text>
            </svg>
            <span
              style={{ fontFamily: "var(--font-display)" }}
              className="text-[15px] tracking-[0.14em] uppercase text-[#F2F3F5]"
            >
              Meridian
            </span>
          </motion.div>

          <div className="w-full max-w-sm mx-auto lg:mx-0 py-16">
            <motion.h1
              initial="hidden"
              animate="show"
              custom={0}
              variants={fade}
              style={{ fontFamily: "var(--font-display)" }}
              className="text-[32px] leading-[1.15] font-medium mb-2"
            >
              Sign in to your account
            </motion.h1>
            <motion.p initial="hidden" animate="show" custom={1} variants={fade} className="text-sm text-[#8B93A3] mb-9">
              Enter your credentials to access the operations console.
            </motion.p>

            <form className="space-y-5" onSubmit={(e) => e.preventDefault()}>
              <motion.div initial="hidden" animate="show" custom={2} variants={fade}>
                <label htmlFor="email" className="block text-xs text-[#8B93A3] mb-2">
                  Work email
                </label>
                <input
                  id="email"
                  type="email"
                  autoComplete="email"
                  placeholder="you@company.com"
                  className="w-full bg-[#13161D] border border-[#262B36] rounded-md px-3.5 py-2.5 text-sm text-[#F2F3F5] placeholder:text-[#4A5160] outline-none transition-colors focus:border-[#C79A4B] focus:ring-1 focus:ring-[#C79A4B]/40"
                />
              </motion.div>

              <motion.div initial="hidden" animate="show" custom={3} variants={fade}>
                <div className="flex items-center justify-between mb-2">
                  <label htmlFor="password" className="block text-xs text-[#8B93A3]">
                    Password
                  </label>
                  <Link href="#" className="text-xs text-[#C79A4B] hover:text-[#DDB268] transition-colors">
                    Forgot password?
                  </Link>
                </div>
                <div className="relative">
                  <input
                    id="password"
                    type={showPassword ? "text" : "password"}
                    autoComplete="current-password"
                    placeholder="••••••••••••"
                    className="w-full bg-[#13161D] border border-[#262B36] rounded-md px-3.5 py-2.5 pr-10 text-sm text-[#F2F3F5] placeholder:text-[#4A5160] outline-none transition-colors focus:border-[#C79A4B] focus:ring-1 focus:ring-[#C79A4B]/40"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword((s) => !s)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-[#4A5160] hover:text-[#8B93A3] transition-colors"
                    aria-label={showPassword ? "Hide password" : "Show password"}
                  >
                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </motion.div>

              <motion.div initial="hidden" animate="show" custom={4} variants={fade} className="flex items-center gap-2 pt-1">
                <input
                  id="remember"
                  type="checkbox"
                  className="w-3.5 h-3.5 rounded-sm bg-[#13161D] border border-[#262B36] accent-[#C79A4B]"
                />
                <label htmlFor="remember" className="text-xs text-[#8B93A3]">
                  Keep me signed in on this device
                </label>
              </motion.div>

              <motion.button
                initial="hidden"
                animate="show"
                custom={5}
                variants={fade}
                type="submit"
                whileHover={{ y: -1 }}
                whileTap={{ y: 0 }}
                className="w-full flex items-center justify-center gap-2 bg-[#C79A4B] hover:bg-[#D6AB5F] text-[#0B0D12] text-sm font-medium rounded-md py-2.5 transition-colors mt-2"
              >
                <span>Sign in</span>
                <ArrowRight className="w-3.5 h-3.5" />
              </motion.button>
            </form>

            <motion.div initial="hidden" animate="show" custom={6} variants={fade} className="my-7 flex items-center gap-3">
              <div className="h-px flex-1 bg-[#262B36]" />
              <span className="text-[11px] text-[#4A5160] uppercase tracking-wider">or continue with</span>
              <div className="h-px flex-1 bg-[#262B36]" />
            </motion.div>

            <motion.div initial="hidden" animate="show" custom={7} variants={fade} className="grid grid-cols-2 gap-3">
              <button className="flex items-center justify-center gap-2 border border-[#262B36] rounded-md py-2.5 text-sm text-[#F2F3F5] hover:border-[#3A4150] hover:bg-[#13161D] transition-colors">
                <svg width="15" height="15" viewBox="0 0 24 24">
                  <path fill="#EA4335" d="M12 10.2v3.9h5.5c-.24 1.4-1.7 4.1-5.5 4.1-3.3 0-6-2.7-6-6.1s2.7-6.1 6-6.1c1.9 0 3.1.8 3.9 1.5l2.6-2.5C16.9 3.4 14.7 2.4 12 2.4 6.9 2.4 2.7 6.6 2.7 11.7S6.9 21 12 21c5.4 0 8.9-3.8 8.9-9.1 0-.6-.1-1.1-.2-1.6H12z" />
                </svg>
                Google
              </button>
              <button className="flex items-center justify-center gap-2 border border-[#262B36] rounded-md py-2.5 text-sm text-[#F2F3F5] hover:border-[#3A4150] hover:bg-[#13161D] transition-colors">
                <svg width="15" height="15" viewBox="0 0 24 24">
                  <path fill="#F35325" d="M2 2h9.5v9.5H2z" />
                  <path fill="#81BC06" d="M12.5 2H22v9.5h-9.5z" />
                  <path fill="#05A6F0" d="M2 12.5h9.5V22H2z" />
                  <path fill="#FFBA08" d="M12.5 12.5H22V22h-9.5z" />
                </svg>
                Microsoft
              </button>
            </motion.div>

            <motion.p initial="hidden" animate="show" custom={8} variants={fade} className="text-xs text-[#4A5160] mt-9">
              No account yet?{" "}
              <Link href="#" className="text-[#C79A4B] hover:text-[#DDB268] transition-colors">
                Request access
              </Link>
            </motion.p>
          </div>

          <div className="text-[11px] text-[#4A5160]">© 2026 Meridian Logistics Platform</div>
        </div>

        {/* ---------------- Right: Visual (your existing Network3D) ---------------- */}
        <div className="hidden lg:block relative bg-[#0E1117] overflow-hidden">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 1.2, delay: 0.2 }}
            className="absolute inset-0"
          >
            <Network3D darkMode />
          </motion.div>

          {/* Manifest ledger stub */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.7, delay: 0.6, ease: [0.22, 1, 0.36, 1] }}
            className="absolute bottom-10 right-10 w-[300px] bg-[#0B0D12]/90 backdrop-blur-sm border border-[#262B36] rounded-lg overflow-hidden"
            style={{ fontFamily: "var(--font-mono)" }}
          >
            <div className="flex items-center justify-between px-4 py-3 border-b border-dashed border-[#262B36]">
              <span className="text-[10px] uppercase tracking-widest text-[#8B93A3]">Live Manifest</span>
              <span className="text-[10px] text-[#4A5160]">29 AUG 2026</span>
            </div>
            <div className="divide-y divide-[#1A1E27]">
              {MANIFEST.map((m) => (
                <div key={m.code} className="flex items-center justify-between px-4 py-2.5 text-[11px]">
                  <div className="flex items-center gap-2">
                    <StatusDot status={m.status} />
                    <span className="text-[#F2F3F5]">{m.code}</span>
                  </div>
                  <span className="text-[#8B93A3]">{m.route}</span>
                  <span className="text-[#4A5160]">{m.eta}</span>
                </div>
              ))}
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.8, delay: 0.9 }}
            className="absolute top-10 left-10 max-w-xs"
          >
            <p style={{ fontFamily: "var(--font-display)" }} className="text-[15px] text-[#8B93A3] leading-snug">
              A single source of truth for every lane, port, and shipment.
            </p>
          </motion.div>
        </div>
      </div>
    </div>
  );
}